### ① Concept Explanation

Elasticsearch is the production standard for BM25-based search. It wraps Apache Lucene, which implements BM25 as the default similarity since Lucene 5+ (Elasticsearch 5+). Elasticsearch adds: distributed search across shards, NRT (near-real-time) indexing, rich query DSL, field boosting, synonyms, suggesters, and aggregations. BM25 parameters (k1, b) are configured per-index in the `similarity` settings. Elasticsearch uses **per-shard IDF** by default (fast but slightly inaccurate for small indexes); global IDF is achieved with `search_type=dfs_query_then_fetch`.

### ② Complete Elasticsearch BM25 Setup

```python
from elasticsearch import Elasticsearch
import json

es = Elasticsearch("http://localhost:9200")

# ── 1. Index Creation with BM25 Configuration ──────────────
def create_bm25_index(index_name: str = "bm25_demo",
                      k1: float = 1.5, b: float = 0.75):
    """Create Elasticsearch index with configured BM25."""
    if es.indices.exists(index=index_name):
        es.indices.delete(index=index_name)

    settings = {
        "settings": {
            "number_of_shards": 1,
            "number_of_replicas": 0,
            "similarity": {
                "my_bm25": {
                    "type": "BM25",
                    "k1": k1,
                    "b": b,
                    "discount_overlaps": True,  # don't count overlapping tokens
                }
            },
            "analysis": {
                "analyzer": {
                    "my_analyzer": {
                        "type": "custom",
                        "tokenizer": "standard",
                        "filter": ["lowercase", "english_stop", "english_stemmer"]
                    }
                },
                "filter": {
                    "english_stop": {
                        "type": "stop",
                        "stopwords": "_english_"
                    },
                    "english_stemmer": {
                        "type": "stemmer",
                        "language": "english"
                    }
                }
            }
        },
        "mappings": {
            "properties": {
                "title": {
                    "type": "text",
                    "analyzer": "my_analyzer",
                    "similarity": "my_bm25",
                },
                "body": {
                    "type": "text",
                    "analyzer": "my_analyzer",
                    "similarity": "my_bm25",
                },
                "id": {"type": "keyword"},
            }
        }
    }
    es.indices.create(index=index_name, body=settings)
    print(f"Created index '{index_name}' with k1={k1}, b={b}")

create_bm25_index()

# ── 2. Document Indexing ─────────────────────────────────────
docs = [
    {"id": "1", "title": "BM25 ranking algorithm",
     "body": "BM25 is a probabilistic retrieval function used in Elasticsearch."},
    {"id": "2", "title": "Elasticsearch search guide",
     "body": "Elasticsearch provides BM25 as the default similarity function."},
    {"id": "3", "title": "Dense retrieval with BERT",
     "body": "BERT-based models use embeddings for semantic search beyond BM25."},
]
for doc in docs:
    es.index(index="bm25_demo", id=doc["id"], document=doc)
es.indices.refresh(index="bm25_demo")

# ── 3. BM25 Search Query ────────────────────────────────────
def bm25_search(query: str, index: str = "bm25_demo", size: int = 10):
    """Standard BM25 search with explanation."""
    result = es.search(
        index=index,
        body={
            "query": {"match": {"body": {"query": query}}},
            "size": size,
            "explain": True,  # show scoring breakdown
        }
    )
    for hit in result["hits"]["hits"]:
        print(f"Score={hit['_score']:.4f}: {hit['_source']['title']}")

bm25_search("BM25 Elasticsearch ranking")

# ── 4. Multi-field BM25 search (approximate BM25F) ──────────
def multi_field_bm25(query: str, index: str = "bm25_demo"):
    """Multi-field BM25 with field boosting."""
    result = es.search(
        index=index,
        body={
            "query": {
                "multi_match": {
                    "query": query,
                    "fields": ["title^3", "body^1"],  # title 3× more important
                    "type": "most_fields",
                    "tie_breaker": 0.3,
                }
            }
        }
    )
    return result

# ── 5. Exact BM25F via cross_fields ─────────────────────────
def cross_fields_bm25f(query: str, index: str = "bm25_demo"):
    """Better approximation of true BM25F scoring."""
    result = es.search(
        index=index,
        body={
            "query": {
                "multi_match": {
                    "query": query,
                    "fields": ["title^3", "body^1"],
                    "type": "cross_fields",  # pools fields, closer to BM25F
                    "operator": "or",
                }
            }
        }
    )
    return result
```

### ③ Scenarios

**S1. 🐢 Elasticsearch BM25 scores differ drastically between shards — IDF discrepancy fix.**

```python
# Problem: per-shard IDF makes small indexes give inconsistent scores

# Fix 1: Single shard (for small indexes)
es.indices.put_settings(
    index="bm25_demo",
    body={"number_of_shards": 1}  # set at creation time — cannot change after
)

# Fix 2: Use dfs_query_then_fetch for global IDF
result_global = es.search(
    index="bm25_demo",
    params={"search_type": "dfs_query_then_fetch"},  # collect global stats first
    body={"query": {"match": {"body": "BM25 ranking"}}, "size": 5}
)
print("Global IDF search results:")
for hit in result_global["hits"]["hits"]:
    print(f"  Score={hit['_score']:.4f}: {hit['_source']['title']}")
```

